#!/usr/bin/env node
// RichDoctor's window, walked in WebKit (the engine its webview uses) from the real files in
// crates/richdoctor/ui, with the app's commands and events stood in for by a scripted backend.
// It drives round 39's journey the way a person does and asserts each step, and runs the RichOS
// app's own contrast probe (ui/tests/lib/contrast.js, the walk its contrast suite runs) on every
// state in both themes: WCAG AA is a floor, computed, never eyeballed.
//
//   node richos/app/scripts/richdoctor-ui-walk.js
//
// The faces and tokens the window loads are generated by crates/richdoctor/build.rs; this walk
// generates them the same way first (tokens from ui/style.css, faces from ui/fonts) into a
// scratch copy of the window, so it runs without a cargo build and never writes the checkout.
"use strict";
const fs = require("fs");
const os = require("os");
const path = require("path");

const APP = path.resolve(__dirname, "..");
const UI = path.join(APP, "crates", "richdoctor", "ui");
const { loadPlaywright } = require(path.join(APP, "ui", "tests", "lib", "harness.js"));
const { pageScript } = require(path.join(APP, "ui", "tests", "lib", "contrast.js"));

let failures = 0;
function ok(name) { console.log("ok   " + name); }
function bad(name, why) { failures++; console.log("FAIL " + name + ": " + why); }
function check(name, cond, why) { if (cond) ok(name); else bad(name, why || "not as expected"); }

// ---- a scratch copy of the window, with the generated files build.rs writes ------------------
function stage() {
  const dir = fs.mkdtempSync(path.join(os.tmpdir(), "rd-ui-"));
  for (const f of fs.readdirSync(UI)) {
    const src = path.join(UI, f);
    if (fs.statSync(src).isFile()) fs.copyFileSync(src, path.join(dir, f));
  }
  fs.mkdirSync(path.join(dir, "fonts"));
  for (const f of fs.readdirSync(path.join(APP, "ui", "fonts"))) fs.copyFileSync(path.join(APP, "ui", "fonts", f), path.join(dir, "fonts", f));
  const css = fs.readFileSync(path.join(APP, "ui", "style.css"), "utf8").split("\n");
  const block = (head) => { const s = css.findIndex((l) => l.trimEnd() === head); const e = css.slice(s).indexOf("}"); return css.slice(s, s + e + 1).join("\n"); };
  fs.writeFileSync(path.join(dir, "tokens.css"), block(":root {") + "\n\n" + block(':root[data-theme="light"] {') + "\n");
  return dir;
}

// ---- the stand-in backend: the commands lib.rs defines, the events engine.rs emits ------------
const REVIEW = {
  mode: "draft", report_id: "RD-7K3M-Q9VX", old_id: null, title: "RichOS 1.2.1 closes before its window opens",
  sections: [
    { key: "what_happened", heading: "What happened", text: "RichOS closes before its window opens. I tried twice this morning.\n\nExpected: RichOS opens to its usual window." },
    { key: "when", heading: "When", text: "Earlier today, October 22, 2026 (UTC-07:00)." },
    { key: "versions", heading: "Versions", text: "RichDoctor 1.0.0\nmacOS 15.6 · Apple silicon · 16 GB memory\nRichOS 1.2.1 in Applications" },
  ],
  excerpts: [
    { evidence_id: "ev-0123456789ab", source_line: "Startup log · 8:43 AM", text: "2026-10-22T15:43:02Z RichOS 1.2.1 pid 4242\nexecutable: [path removed]\nfailure: the engine did not start", removed: false },
    { evidence_id: "ev-0123456789ac", source_line: "Launch record · 8:43 AM", text: "No start recorded in the incident window.", removed: false },
  ],
  screenshots: 0,
  after: [
    { key: "causes", heading: "Possible cause (not confirmed)", text: "The engine may be failing to start (from the startup log)." },
    { key: "missing", heading: "Missing information", text: "• No crash record for RichOS was on this Mac.\n• RichOS's own runtime log is not written when RichOS is opened from Finder, the Dock or Spotlight, so it is not included." },
  ],
  footer: "Sent with RichDoctor 1.0 · Report ID RD-7K3M-Q9VX",
  notes: ["Removed automatically before this review: 1 file path (startup log), shown as [path removed]. Remove anything else private."],
  exact: "RichOS 1.2.1 closes before its window opens\n\n## What happened\n\nRichOS closes before its window opens.\n\nSent with RichDoctor 1.0 · Report ID RD-7K3M-Q9VX",
  problems: [],
};
const DELIVERY = (kind, extra) => ({ kind, report_id: "RD-7K3M-Q9VX", title: REVIEW.title, first: "RichOS closes before its window opens. I tried twice this morning.", summary: "6 sections, 2 diagnostic excerpts, the report ID footer. The exact text is in Saved reports.", extra: extra || {} });

function backend(state) {
  // Runs in the page: window.__TAURI__ as the app's withGlobalTauri provides it.
  window.__calls = [];
  window.__listeners = [];
  window.__emit = function (v) { window.__listeners.forEach(function (f) { f({ payload: v }); }); };
  const S = JSON.parse(state);
  window.__TAURI__ = {
    event: { listen: function (name, f) { window.__listeners.push(f); return Promise.resolve(function () {}); } },
    core: {
      invoke: function (cmd, args) {
        window.__calls.push([cmd, args || {}]);
        const R = S.replies[cmd];
        if (cmd === "start" && !(args.description || "").trim()) return Promise.reject("Describe what went wrong first.");
        return R === undefined ? Promise.resolve(null) : Promise.resolve(JSON.parse(JSON.stringify(R)));
      },
    },
  };
}

const BOOT = { installation: "Found RichOS 1.2.1 (nightly 68) in Applications.", ambiguous: false, claude_found: true, resume: null, login: { on: true, denied: false }, mail: true, support: "support@richos.ceo", destination_ok: true };
const SAVED = { rows: [
  { id: "d-0123456789ab", title: "RichOS 1.2.1 closes before its window opens", date: "October 22, 2026", left: "sent at 8:52 AM", state: "submitted", state_words: "Report submitted", action: "view", issue_url: "https://github.com/WebDevBooster/richos/issues/412" },
  { id: "d-0123456789ac", title: "Rich's answer stops mid-way", date: "October 20, 2026", left: "draft, interrupted during the investigation", state: "saved", state_words: "Saved on this Mac", action: "resume", issue_url: null },
  { id: "d-0123456789ad", title: "RichScribe stops transcribing mid-sentence", date: "October 18, 2026", left: "approved, checked at 9:41 AM", state: "unconfirmed", state_words: "Delivery could not be confirmed", action: "check", issue_url: null },
  { id: "d-0123456789ae", title: "RichOS window went blank after the Mac woke up", date: "October 15, 2026", left: "approved, not sent yet", state: "notsent", state_words: "Not sent yet · connection failed", action: "try", issue_url: null },
], sent: [] };

async function contrast(page, name, theme) {
  await page.addScriptTag({ content: pageScript() });
  const r = await page.evaluate(({ surface, theme }) => window.__contrastProbe({ surface, theme }), { surface: name, theme });
  const keys = (o) => Object.keys(o || {});
  const fails = keys(r.failures).length + keys(r.indicators && r.indicators.failures).length;
  if (fails) bad(`contrast ${name} ${theme}`, JSON.stringify(Object.assign({}, r.failures, r.indicators && r.indicators.failures)).slice(0, 1500));
  else ok(`contrast ${name} ${theme}: ${r.nodesPassed}/${r.nodesChecked} text, ${r.indicators.passed}/${r.indicators.checked} indicators`);
}

async function run() {
  const pw = loadPlaywright();
  const dir = stage();
  const browser = await pw.webkit.launch();
  try {
    for (const theme of ["dark", "light"]) {
      const ctx = await browser.newContext({ viewport: { width: 760, height: 760 }, colorScheme: theme });
      const page = await ctx.newPage();
      const errors = [];
      page.on("pageerror", (e) => errors.push(String(e)));
      page.on("console", (m) => { if (m.type() === "error") errors.push(m.text()); });
      await page.addInitScript(backend, JSON.stringify({ replies: { boot: BOOT, review: REVIEW, saved: SAVED, excerpt: Object.assign({}, REVIEW, { excerpts: [Object.assign({}, REVIEW.excerpts[0]), Object.assign({}, REVIEW.excerpts[1], { removed: true })] }), mail_available: true, delivery: DELIVERY("unconfirmed", { checked_at: "9:47 AM" }) } }));
      await page.goto("file://" + path.join(dir, "index.html"));
      await page.evaluate(() => document.fonts.ready);
      const T = (sel) => page.locator(sel).first().innerText();
      const visible = (sel) => page.locator(sel).first().isVisible();
      const emit = (v) => page.evaluate((v) => window.__emit(v), v);
      const calls = () => page.evaluate(() => window.__calls);
      const settle = () => page.waitForTimeout(120);

      // 1. First opening (round 39 §1)
      await settle();
      check(`${theme} first: installation line`, (await T("#richos-line")) === BOOT.installation);
      check(`${theme} first: login switch reflects macOS`, (await page.getAttribute("#login-sw", "aria-checked")) === "true");
      check(`${theme} first: the two decisions are explained`, (await T("#s-first .card:not(#resume-card)")).includes("Nothing becomes public"));
      check(`${theme} first: focus starts in What went wrong?`, await page.evaluate(() => document.activeElement && document.activeElement.id === "desc"));
      await contrast(page, "first", theme);
      await page.click('[data-act="continue"]');
      await settle();
      check(`${theme} first: an empty description is not started`, (await calls()).every((c) => c[0] !== "start") && (await visible("#s-first")));
      await page.fill("#desc", "RichOS closes before its window opens. I tried twice this morning.");
      await page.click('[data-act="continue"]');
      await settle();
      const start = (await calls()).find((c) => c[0] === "start");
      check(`${theme} start: Continue starts with AI and diagnostics`, start && start[1].withoutAi === false && start[1].noDiagnostics === false);
      check(`${theme} conversation: shown`, await visible("#s-conv"));

      // 2. The conversation (round 39 §2)
      await emit({ t: "me", text: "RichOS closes before its window opens. I tried twice this morning." });
      await emit({ t: "question", text: "Thanks. About when did it last happen?", choices: ["Just now", "Earlier today", "Yesterday", "Enter a time…"] });
      await settle();
      check(`${theme} conversation: one question, four choices`, (await page.locator("#log .choices .btn").count()) === 4);
      check(`${theme} conversation: the log announces additions only`, (await page.getAttribute("#log", "aria-relevant")) === "additions" && (await page.getAttribute("#log", "role")) === "log");
      await contrast(page, "conversation", theme);
      await page.locator('#log [data-choice="Earlier today"]').click();
      await settle();
      check(`${theme} conversation: a chip answers`, (await calls()).some((c) => c[0] === "answer" && c[1].text === "Earlier today"));
      await emit({ t: "me", text: "Earlier today" });
      await emit({ t: "progress", text: "Checking what happened when RichOS last opened…" });
      await settle();
      check(`${theme} conversation: progress names the action`, (await T("#log .progress-wrap")).includes("Checking what happened when RichOS last opened"));
      await contrast(page, "progress", theme);
      await emit({ t: "done", text: "Checked what happened when RichOS last opened" });
      await emit({ t: "ai-failed", message: "RichDoctor could not use the default Claude Code sign-in.", retry: true });
      await settle();
      check(`${theme} AI failure: leads with We can still prepare your report.`, (await T("#log .fail h2")) === "We can still prepare your report.");
      check(`${theme} AI failure: Retry and Prepare report now`, (await visible('#log .fail [data-act="retry-ai"]')) && (await visible('#log .fail [data-act="prepare-now"]')));
      await contrast(page, "aifail", theme);
      await emit({ t: "ai-failed", message: "Claude Code was not found on this Mac.", retry: false });
      await settle();
      check(`${theme} AI failure: no Retry when Claude Code is not installed`, (await page.locator('#log .fail [data-act="retry-ai"]').count()) === 0);
      await emit({ t: "canceled" });
      await settle();
      check(`${theme} cancel: Resume investigation is offered, nothing re-runs`, (await visible('#log .fail [data-act="resume-inv"]')) && (await T("#log .fail h2")) === "Investigation canceled.");
      await emit({ t: "ready" });
      await settle();
      check(`${theme} ready: Review report takes the primary place`, (await visible("#conv-review")) && !(await visible("#conv-prepare")));
      check(`${theme} ready: focus moves to Review report`, await page.evaluate(() => document.activeElement && document.activeElement.id === "conv-review"));

      // 3. Review (round 39 §4)
      await emit({ t: "review" });
      await page.waitForSelector("#s-review:not([hidden])");
      check(`${theme} review: the title`, (await T("#rv-title")) === REVIEW.title);
      check(`${theme} review: the public destination beside Send`, (await T("#s-review .pub")).includes("This report will be public on GitHub. Review it before sending."));
      check(`${theme} review: the excerpt disclosure is collapsed with its count`, (await page.getAttribute(".disc", "aria-expanded")) === "false" && (await T(".disc .count")).startsWith("2 excerpts"));
      check(`${theme} review: the footer is shown as sent`, (await T("#rv-sections")).includes("Sent with RichDoctor 1.0 · Report ID RD-7K3M-Q9VX"));
      check(`${theme} review: Send report enabled with no problems`, !(await page.locator("#rv-send").isDisabled()));
      await contrast(page, "review", theme);
      await page.click(".disc");
      await settle();
      check(`${theme} review: removal marks shown in gold`, (await page.locator(".ex pre mark").count()) === 1);
      await contrast(page, "review-open", theme);
      await page.locator('.ex [data-act="remove-ex"]').nth(1).click();
      await settle();
      check(`${theme} review: Remove asks the app`, (await calls()).some((c) => c[0] === "excerpt" && c[1].id === "ev-0123456789ac" && c[1].removed === true));
      check(`${theme} review: a removed excerpt can be put back`, (await T(".ex .removed")).includes("removed by you") && (await visible('[data-act="restore-ex"]')));
      await page.click("#rv-exact-toggle");
      check(`${theme} review: the exact text is the same bytes`, (await T("#rv-exact-text")) === REVIEW.exact && (await page.getAttribute("#rv-exact-toggle", "aria-pressed")) === "true");
      await page.click("#rv-exact-toggle");
      await page.evaluate((v) => { window.__TAURI__.core.invoke = ((orig) => function (c, a) { return c === "review" ? Promise.resolve(v) : orig(c, a); })(window.__TAURI__.core.invoke); }, Object.assign({}, REVIEW, { problems: [{ item: "line 9", detail: "This line contains an email address.", line: "mail me at someone@example.com" }] }));
      await emit({ t: "review" });
      await settle();
      check(`${theme} review: a privacy problem blocks Send and names the line`, (await page.locator("#rv-send").isDisabled()) && (await T("#rv-notes")).includes("mail me at someone@example.com"));
      await page.evaluate((v) => { window.__TAURI__.core.invoke = ((orig) => function (c, a) { return c === "review" ? Promise.resolve(v) : orig(c, a); })(window.__TAURI__.core.invoke); }, Object.assign({}, REVIEW, { mode: "revision-uncertain", old_id: "RD-7K3M-Q9VX" }));
      await emit({ t: "review" });
      await settle();
      check(`${theme} revision during uncertainty: Editing a copy, Save edit, no Send`, (await T("#rv-banner")).includes("Editing a copy.") && !(await visible("#rv-send")) && (await visible("#rv-save-edit")));
      await contrast(page, "review-uncertain", theme);

      // 4. Delivery (round 39 §5)
      for (const [kind, extra, want] of [
        ["sending", {}, "Sending your report…"],
        ["sending-screenshots", { done: 1, total: 2 }, "Sending screenshots"],
        ["created-checking", { issue_url: "https://github.com/WebDevBooster/richos/issues/412", confirmed: 1, expected: 2 }, "Report created; checking screenshots"],
        ["checking", {}, "Checking whether your report was received"],
        ["submitted", { issue_url: "https://github.com/WebDevBooster/richos/issues/412" }, "Report submitted"],
        ["notsent", { reason: "Your Mac is not connected to the internet. Try again when you are online.", review: false, try_again: true }, "Not sent yet"],
        ["notsent", { reason: "The reporting service did not accept the report: in the startup log excerpt, one line looks like it contains a password.", review: true, try_again: false }, "Not sent yet"],
        ["unconfirmed", { checked_at: "9:41 AM" }, "Delivery could not be confirmed"],
      ]) {
        await emit({ t: "delivery", view: DELIVERY(kind, extra) });
        await settle();
        const label = kind + (extra.review ? "-rejected" : "");
        check(`${theme} result ${label}: heading`, (await T("#result-body h1")) === want);
        check(`${theme} result ${label}: the report ID, never a secret`, (await T("#result-body .kv")).includes("RD-7K3M-Q9VX"));
        const foot = await T("#result-foot");
        if (kind === "unconfirmed") check(`${theme} result unconfirmed: Check status, no Send or Try again`, foot.includes("Check status") && !foot.includes("Send report") && !foot.includes("Try again"));
        if (kind === "notsent" && !extra.review) check(`${theme} result notsent: the observed reason and Try again`, (await T("#result-body .why")).startsWith("Your Mac is not connected") && foot.includes("Try again"));
        if (kind === "notsent" && extra.review) check(`${theme} result rejected: Review report instead of Try again`, foot.includes("Review report") && !foot.includes("Try again"));
        if (kind === "created-checking") check(`${theme} result created-checking: the real link, Check status, no Send`, (await T("#result-body .issue")) === "github.com/WebDevBooster/richos/issues/412" && foot.includes("Check status") && !foot.includes("Send report"));
        if (kind === "submitted") check(`${theme} result submitted: the public link as its address`, (await T("#result-body .issue")) === "github.com/WebDevBooster/richos/issues/412");
        await contrast(page, "result-" + label, theme);
      }
      await page.click('#result-foot [data-act="email"]');
      await page.waitForSelector("#sheet-email:not([hidden])");
      check(`${theme} email: the address and that the user sends it`, (await T("#em-body")).includes("support@richos.ceo") && (await T("#em-body")).includes("You read it and send it yourself"));
      await contrast(page, "email", theme);
      await page.keyboard.press("Escape");
      check(`${theme} email: Escape closes the sheet`, !(await visible("#sheet-email")));

      // 5. Saved reports (round 39 §6)
      await emit({ t: "go", screen: "saved" });
      await page.waitForSelector("#s-saved:not([hidden])");
      check(`${theme} saved: four rows with their matching action`, (await page.locator("#saved-list .item").count()) === 4 && (await T("#saved-list")).includes("Check status") && (await T("#saved-list")).includes("Resume"));
      await contrast(page, "saved", theme);
      await page.locator('#saved-list [data-act="delete"]').first().click();
      await page.waitForSelector("#sheet-delete:not([hidden])");
      check(`${theme} delete: a sent report's public copy stays`, (await T("#del-p")).includes("The public report on GitHub stays"));
      // load-bound: catches a missing focus only; the window moves it 30 ms after the sheet opens.
      const cancelFocused = await page.waitForFunction(() => document.activeElement && document.activeElement.textContent === "Cancel", null, { timeout: 2000 }).then(() => true, () => false);
      check(`${theme} delete: focus starts on Cancel`, cancelFocused);
      await contrast(page, "delete", theme);
      await page.keyboard.press("Escape");

      // 6. Not saved on this Mac (round 39 §6)
      await emit({ t: "storage", ok: false, sentence: "RichDoctor could not write to its folder: the disk is full." });
      await settle();
      check(`${theme} storage: the banner says it is not saved, and why`, (await T("#unsaved-slot-saved")).includes("Not saved on this Mac.") && (await T("#unsaved-slot-saved")).includes("the disk is full"));
      await contrast(page, "unsaved", theme);

      check(`${theme} no page errors`, errors.length === 0, errors.join(" | "));
      await ctx.close();
    }
  } finally {
    await browser.close();
    fs.rmSync(dir, { recursive: true, force: true });
  }
  console.log(failures ? `richdoctor-ui-walk: ${failures} FAILED` : "richdoctor-ui-walk: passed");
  process.exit(failures ? 1 : 0);
}

run().catch((e) => { console.error(e); process.exit(1); });
